{
  "findings": [
    {
      "check_id": "CKV2_AZURE_31",
      "title": "Ensure VNET subnet is configured with a Network Security Group (NSG)",
      "resource": "azurerm_subnet.changeme_simple_network_interface_subnet",
      "severity": "MEDIUM",
      "explanation": "The subnet 'changeme_simple_network_interface_subnet' is not associated with a Network Security Group (NSG), potentially exposing it to unauthorized access."
    }
  ],
  "patched_code": "resource "azurerm_subnet" "changeme_simple_network_interface_subnet" {
  name                 = "changeme-simple-network-interface-subnet-name"
  resource_group_name  = azurerm_resource_group.changeme_simple_network_interface_resource_group.name
  virtual_network_name = azurerm_virtual_network.changeme_simple_network_interface_virtual_network.name
  address_prefixes     = ["10.0.1.0/24"]

  # Associate a Network Security Group with the subnet
  depends_on = [azurerm_network_security_group.changeme_simple_network_interface_nsg]
}

# Assuming azurerm_network_security_group resource exists or is created
# If not, create it: resource "azurerm_network_security_group" "changeme_simple_network_interface_nsg" { ... }
resource "azurerm_subnet_network_security_group_association" "changeme_simple_network_interface_subnet_nsg_association" {
  subnet_id                 = azurerm_subnet.changeme_simple_network_interface_subnet.id
  network_security_group_id = azurerm_network_security_group.changeme_simple_network_interface_nsg.id
}",
  "fix_summary": "Associated the subnet with a Network Security Group (NSG) by creating a 'azurerm_subnet_network_security_group_association' resource."
}
